 TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local power = 75\n    local duration = 1800\n\n    target:addStatusEffect(xi.effect.PROTECT, { power = power, duration = duration, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/scroll_of_instant_reraise.lua"]={["Path"]="scripts/items/scroll_of_instant_reraise.lua",["SHA256"]="d3e3333572803d2d998fe13239f4eb599e8d1429fa3723439d805abe9d9dc282",["Text"]="-----------------------------------\n-- ID: 4182\n--  Scroll of Instant ReRaise\n--  Brings you back from the dead~!\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local power = 1\n    local duration = 1800\n    if target:hasStatusEffect(xi.effect.RERAISE) then\n        local effect = target:getStatusEffect(xi.effect.RERAISE)\n        if not effect then\n            return\n        end\n\n        local oPower = effect:getPower()\n\n        if oPower > power then\n            target:messageBasic(xi.msg.basic.NO_EFFECT)\n        else\n            target:delStatusEffect(xi.effect.RERAISE)\n            target:addStatusEffect(xi.effect.RERAISE, { power = power, duration = duration, origin = user })\n        end\n    else\n        target:addStatusEffect(xi.effect.RERAISE, { power = power, duration = duration, origin = user })\n    end\nend\n\nreturn itemObject\n"},["scripts/items/scroll_of_instant_retrace.lua"]={["Path"]="scripts/items/scroll_of_instant_retrace.lua",["SHA256"]="f6fdd9cfffe9c46d3fd5478861acac72a8ff5628f566b7a4891503dfb2da6bc5",["Text"]="-----------------------------------\n-- ID: 5428\n-- Scroll of Instant Retrace\n-- Transports the user to their Allied Nation.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getCampaignAllegiance() == 0 then\n        return 56\n    else\n        return 0\n    end\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:getCampaignAllegiance() > 0 then\n        target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.RETRACE, duration = 3, origin = user, icon = 0 })\n    end\nend\n\nreturn itemObject\n"},["scripts/items/scroll_of_instant_shell.lua"]={["Path"]="scripts/items/scroll_of_instant_shell.lua",["SHA256"]="d64081b628f426537900b67ea90f6d7b8a3aa812011c33d53cc2a6c8a29267e0",["Text"]="-----------------------------------\n-- ID: 5989\n--  Scroll of Instant Shell\n--  Grants the effect of Shell\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local power = 1900 -- shell_iii base power\n    local duration = 1800\n\n    target:addStatusEffect(xi.effect.SHELL, { power = power, duration = duration, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/scroll_of_instant_stoneskin.lua"]={["Path"]="scripts/items/scroll_of_instant_stoneskin.lua",["SHA256"]="80649b2fe0db3be8f35b9af7aec39238d849431b3cb8b0ae2860794406e0ef2b",["Text"]="-----------------------------------\n-- ID: 5990\n-- Scroll of Instant Stoneskin\n-- Grants the user a 200 HP Stoneskin effect\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:addStatusEffect(xi.effect.STONESKIN, { power = 200, duration = 300, origin = user, tier = 4 }) then\n        target:messageBasic(xi.msg.basic.GAINS_EFFECT_OF_STATUS, xi.effect.STONESKIN)\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/scroll_of_instant_warp.lua"]={["Path"]="scripts/items/scroll_of_instant_warp.lua",["SHA256"]="2835d86e02df4028e882c59638c8396642a5a1e71c78d694909e33ab9afbfd20",["Text"]="-----------------------------------\n-- ID: 4181\n-- Scroll of Instant Warp\n-- Transports the user to their Home Point\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.WARP, duration = 3, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/scroll_of_inundation.lua"]={["Path"]="scripts/items/scroll_of_inundation.lua",["SHA256"]="e14618dc99d5df72987201a5c0a97c9ca3bc70c19411c1aba901d55679f29876",["Text"]="-----------------------------------\n-- ID: 5106\n-- Scroll of Inundation\n-- Teaches the white Inundation\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.INUNDATION)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.INUNDATION)\nend\n\nreturn itemObject\n"},["scripts/items/scroll_of_invisible.lua"]={["Path"]="scripts/items/scroll_of_invisible.lua",["SHA256"]="a2bf54345499dabcc3f25f914d8a827652c2a5503f0ed8a60a8ed52c81147344",["Text"]="-----------------------------------\n-- ID: 4744\n-- Scroll of Invisible\n-- Teaches the white magic Invisible\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.INVISIBLE)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.INVISIBLE)\nend\n\nreturn itemObject\n"},["scripts/items/scroll_of_jubaku_ichi.lua"]={["Path"]="scripts/items/scroll_of_jubaku_ichi.lua",["SHA256"]="34b85289baea403febf55dd2d31f3e24020d1e1bca0120d32b94476e34586da0",["Text"]="--------